import re, os, shutil, zipfile, sys

SRC = '/mnt/spreadsheet_data/spreadsheet/10_Debugging/input_files/Inconsistent Color Coding_input.xlsx'
OUT = '/mnt/spreadsheet_output/10_04_output.xlsx'
WORK = '/tmp/work_extract'

if os.path.exists(WORK):
    shutil.rmtree(WORK)
os.makedirs(WORK)
with zipfile.ZipFile(SRC) as z:
    z.extractall(WORK)

# ---------- defined names (for bare-name pure references) ----------
wbxml = open(os.path.join(WORK, 'xl/workbook.xml'), encoding='utf-8').read()
defined_names = set()
for m in re.finditer(r'<definedName name="([^"]+)"[^>]*>([^<]*)</definedName>', wbxml):
    nm = m.group(1)
    if re.fullmatch(r'[A-Za-z_\\][A-Za-z0-9_.\\]*', nm):
        defined_names.add(nm.lower())

# ---------- styles ----------
styles_path = os.path.join(WORK, 'xl/styles.xml')
styles = open(styles_path, encoding='utf-8').read()

mfonts = re.search(r'<fonts([^>]*)>(.*?)</fonts>', styles, re.S)
fonts_attrs, fonts_inner = mfonts.group(1), mfonts.group(2)
font_list = re.findall(r'<font(?:[^>]*)>.*?</font>|<font[^>]*/>', fonts_inner, re.S)
# fallback simple split
if not font_list:
    raise RuntimeError('no fonts parsed')

mcellxfs = re.search(r'<cellXfs([^>]*)>(.*?)</cellXfs>', styles, re.S)
cellxfs_attrs, cellxfs_inner = mcellxfs.group(1), mcellxfs.group(2)
xf_list = re.findall(r'<xf[^>]*/>|<xf[^>]*>.*?</xf>', cellxfs_inner, re.S)
if not xf_list:
    raise RuntimeError('no xfs parsed')

def font_color_class(fstr):
    m = re.search(r'<color[^>]*/>', fstr)
    if not m:
        return 'none'
    c = m.group(0)
    if 'theme="1"' in c:
        return 'black'
    if 'rgb="FF00B050"' in c:
        return 'green'
    if 'rgb="FF0000FF"' in c:
        return 'blue'
    return 'other:' + c

COLOR_XML = {'black': '<color theme="1"/>', 'green': '<color rgb="FF00B050"/>', 'blue': '<color rgb="FF0000FF"/>'}

font_index = {}
for i, f in enumerate(font_list):
    font_index.setdefault(f, i)

def get_font_with_color(fstr, target):
    """return index of font identical to fstr but with target color"""
    cur = font_color_class(fstr)
    if cur == target:
        return font_index[fstr]
    if '<color' in fstr:
        nf = re.sub(r'<color[^>]*/>', COLOR_XML[target], fstr, count=1)
    else:
        if '<sz' in fstr:
            nf = re.sub(r'(<sz[^>]*/>)', r'\1' + COLOR_XML[target], fstr, count=1)
        else:
            nf = fstr.replace('<font>', '<font>' + COLOR_XML[target], 1)
            nf = re.sub(r'<font([^>]*)>', lambda mm: '<font%s>' % mm.group(1), nf) if False else nf
    if nf not in font_index:
        font_index[nf] = len(font_list)
        font_list.append(nf)
    return font_index[nf]

xf_index = {}
for i, x in enumerate(xf_list):
    xf_index.setdefault(x, i)

xf_cache = {}  # (xf_idx, font_idx) -> new idx

def get_xf_with_font(xf_idx, font_idx):
    key = (xf_idx, font_idx)
    if key in xf_cache:
        return xf_cache[key]
    x = xf_list[xf_idx]
    # modify fontId
    if 'fontId="' in x:
        nx = re.sub(r'fontId="\d+"', 'fontId="%d"' % font_idx, x, count=1)
    else:
        nx = re.sub(r'<xf', '<xf fontId="%d"' % font_idx, x, count=1)
    # ensure applyFont="1"
    if 'applyFont="' in nx:
        nx = re.sub(r'applyFont="[^"]*"', 'applyFont="1"', nx, count=1)
    else:
        if '/>' in nx.split('>', 1)[0] or nx.endswith('/>'):
            nx = nx.replace('/>', ' applyFont="1"/>', 1) if nx.endswith('/>') else nx
        else:
            nx = re.sub(r'<xf([^>]*)>', lambda mm: '<xf%s applyFont="1">' % mm.group(1), nx, count=1)
    if nx not in xf_index:
        xf_index[nx] = len(xf_list)
        xf_list.append(nx)
    xf_cache[key] = xf_index[nx]
    return xf_cache[key]

# ---------- classification ----------
REF_RE = re.compile(r"^(?:'[^']+'|[A-Za-z_][A-Za-z0-9_.]*!)?\$?[A-Z]{1,3}\$?\d+(?::\$?[A-Z]{1,3}\$?\d+)?$")
COLREF_RE = re.compile(r"^(?:'[^']+'|[A-Za-z_][A-Za-z0-9_.]*!)?\$?[A-Z]{1,3}:\$?[A-Z]{1,3}$")
NAME_RE = re.compile(r"^[A-Za-z_\\][A-Za-z0-9_.\\]*$")

def classify_formula(ftext):
    t = ftext.strip()
    if REF_RE.match(t) or COLREF_RE.match(t):
        return 'green'
    if NAME_RE.match(t) and t.lower() in defined_names:
        return 'green'
    return 'black'

CELL_RE = re.compile(r'<c r="([A-Z]+\d+)"([^>]*?)(/>|>(.*?)</c>)', re.S)
FMASTER_RE = re.compile(r'<f[^>]*si="(\d+)"[^>]*>(.*?)</f>', re.S)
FCHILD_RE = re.compile(r'<f[^>]*si="(\d+)"[^>]*/>')
FTEXT_RE = re.compile(r'<f[^>]*>(.*?)</f>', re.S)

stats = {}
def process_sheet(path):
    global font_list, font_index, xf_list, xf_index
    s = open(path, encoding='utf-8').read()
    # pass 1: collect shared formula masters
    masters = {}
    for mm in FMASTER_RE.finditer(s):
        masters[mm.group(1)] = mm.group(2)
    changes = {'green': 0, 'black': 0, 'blue': 0}

    def repl(m):
        coord, attrs, tail, inner = m.group(1), m.group(2), m.group(3), m.group(4)
        target = None
        if inner and '<f' in inner:
            fm = FTEXT_RE.search(inner)
            if fm and fm.group(1) is not None and fm.group(1) != '':
                target = classify_formula(fm.group(1))
            else:
                fc = FCHILD_RE.search(inner)
                if fc and fc.group(1) in masters:
                    target = classify_formula(masters[fc.group(1)])
                else:
                    return m.group(0)
        else:
            if 't="s"' in attrs or 't="inlineStr"' in attrs or 't="str"' in attrs or 't="e"' in attrs:
                return m.group(0)
            if 't="b"' in attrs:
                target = 'blue'
            elif inner and '<v>' in inner:
                target = 'blue'
            else:
                return m.group(0)
        if target is None:
            return m.group(0)
        sm = re.search(r's="(\d+)"', attrs)
        xf_idx = int(sm.group(1)) if sm else 0
        cur_font_idx = None
        fx = re.search(r'fontId="(\d+)"', xf_list[xf_idx])
        cur_font_idx = int(fx.group(1)) if fx else 0
        cur_class = font_color_class(font_list[cur_font_idx])
        if cur_class == target:
            return m.group(0)
        new_font_idx = get_font_with_color(font_list[cur_font_idx], target)
        new_xf_idx = get_xf_with_font(xf_idx, new_font_idx)
        if sm:
            new_attrs = re.sub(r's="\d+"', 's="%d"' % new_xf_idx, attrs, count=1)
        else:
            new_attrs = attrs + ' s="%d"' % new_xf_idx
        changes[target] += 1
        return '<c r="%s"%s%s' % (coord, new_attrs, tail)

    s2 = CELL_RE.sub(repl, s)
    if s2 != s:
        open(path, 'w', encoding='utf-8').write(s2)
    return changes

ws_dir = os.path.join(WORK, 'xl/worksheets')
total = {'green': 0, 'black': 0, 'blue': 0}
for fn in sorted(os.listdir(ws_dir)):
    if fn.endswith('.xml') and os.path.isfile(os.path.join(ws_dir, fn)):
        ch = process_sheet(os.path.join(ws_dir, fn))
        for k in total:
            total[k] += ch[k]
        print(fn, ch)

# ---------- write styles back ----------
new_fonts_block = '<fonts%s>' % fonts_attrs[:-1] if fonts_attrs.endswith('/') else '<fonts%s>' % fonts_attrs
# rebuild fonts block: keep original attrs but fix count
fa = re.sub(r'count="\d+"', 'count="%d"' % len(font_list), fonts_attrs)
new_fonts_block = '<fonts%s>%s</fonts>' % (fa, ''.join(font_list))
ca = re.sub(r'count="\d+"', 'count="%d"' % len(xf_list), cellxfs_attrs)
new_cellxfs_block = '<cellXfs%s>%s</cellXfs>' % (ca, ''.join(xf_list))
styles = styles[:mfonts.start()] + new_fonts_block + styles[mfonts.end():]
# recompute cellXfs position after replacement
m2 = re.search(r'<cellXfs[^>]*>.*?</cellXfs>', styles, re.S)
styles = styles[:m2.start()] + new_cellxfs_block + styles[m2.end():]
open(styles_path, 'w', encoding='utf-8').write(styles)

print('TOTAL changes:', total)
print('fonts:', len(font_list), 'xfs:', len(xf_list))

# ---------- rezip ----------
out_dir = os.path.dirname(OUT)
os.makedirs(out_dir, exist_ok=True)
if os.path.exists(OUT):
    os.remove(OUT)
with zipfile.ZipFile(OUT, 'w', zipfile.ZIP_DEFLATED) as z:
    for root, dirs, files in os.walk(WORK):
        for f in files:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, WORK)
            z.write(full, rel)
print('written', OUT)

