f=wb['Formats']; rt=wb['Report Tables']

CA='Consol_annual'
cols=['T','U','V','W','X','Y','Z','AA','AB']  # FY19A..FY27E
table_cols=['E','F','G','H','I','J','K','L','M']

# --- First Consolidated Financials table (D4:M25) -> link to Consol_annual ---
row_map={4:6, 5:22, 6:8, 7:30, 8:28, 9:42, 11:164, 12:158, 13:127,
         15:101, 16:107, 17:105, 18:88, 22:120, 23:117, 24:23}
for tr,sr in row_map.items():
    for tc,cc in zip(table_cols,cols):
        f[f'{tc}{tr}']=f'={CA}!{cc}{sr}'
# Recurring PAT = Reported PAT - extraordinaires
for tc,cc in zip(table_cols,cols):
    f[f'{tc}10']=f'={CA}!{cc}42-{CA}!{cc}41'
# P/E, P/B, EV/EBITDA
for i,tc in enumerate(table_cols):
    f[f'{tc}19']=f'=$B$4/{CA}!{cols[i]}101'
    f[f'{tc}20']=f'=$B$4/{CA}!{cols[i]}107'
    f[f'{tc}21']=f'=($B$19+{tc}12-{tc}13)/{tc}5'
# Net Margin (%)
for tc in table_cols:
    f[f'{tc}25']=f'={tc}9/{tc}4'

# --- Logical functions below Quarterly Result Table (rows 50,52,54,56,59,61,63) ---
for r,src in [(50,5),(52,17),(54,24),(56,30),(59,35),(61,36),(63,39)]:
    f[f'AY{r}']=f'=IF(BC{src}>0,"+","–")'
    f[f'AZ{r}']=f'=IF(BB{src}>0,"+","–")'
    f[f'BA{r}']=f'=IF(BA{src}>0,"ahead","below")'

# --- Report Tables: Particulars table links ---
link_map={4:5,5:7,6:8,7:9,8:11,10:15,12:17,13:18,15:20,16:21,17:22,
          19:24,20:25,22:27,23:28,24:29,25:30,26:31,27:32,28:33}
fmt_cols=['AW','AX','AY','AZ']   # 3QFY24,3QFY24E,2QFY24,3QFY23
pct_cols=['BA','BB','BC']
for rr,fr in link_map.items():
    for pc,fc in zip(['C','D','E','F'],fmt_cols):
        rt[f'{pc}{rr}']=f'=Formats!{fc}{fr}'
    for pc,fc in zip(['G','H','I'],pct_cols):
        if f.value_dummy if False else True:
            # link where Formats has the % change; else compute
            if f[f'{fc}{fr}'].value is not None:
                rt[f'{pc}{rr}']=f'=Formats!{fc}{fr}'
            else:
                if pc=='G':
                    rt[f'{pc}{rr}']=f'=IFERROR(C{rr}/D{rr}-1,0)'
                elif pc=='H':
                    rt[f'{pc}{rr}']=f'=IFERROR(C{rr}/E{rr}-1,0)'
                else:
                    rt[f'{pc}{rr}']=f'=IFERROR(C{rr}/F{rr}-1,0)'
# Cost items as % of sales (calculated) + bps % change
for rr,fr in [(30,42),(31,43),(32,44)]:
    for pc,fc in zip(['C','D','E','F'],fmt_cols):
        rt[f'{pc}{rr}']=f'=Formats!{fc}{fr}/Formats!{fc}$5'
    rt[f'G{rr}']=(f'=(C{rr}-D{rr})*10000')
    rt[f'H{rr}']=(f'=(C{rr}-E{rr})*10000')
    rt[f'I{rr}']=(f'=(C{rr}-F{rr})*10000')
# Margin (%) section: link levels, calculate bps changes
