import openpyxl
p="/mnt/spreadsheet_data/spreadsheet/02_cash_sweep/02_05_input.xlsx"
wb=openpyxl.load_workbook(p)
ws=wb["DebtWaterfall"]
cols=[3,4,5,6]
def g(r,c): return ws.cell(row=r,column=c).value
req={c:g(7,c) for c in cols}
ocf={c:g(8,c) for c in cols}
init={'rev':580,'tla':2100,'tlb':650}
end_debt={'rev':{},'tla':{},'tlb':{}}
rates={'rev':15,'tla':22,'tlb':29}
begb={'rev':12,'tla':19,'tlb':26}
rep_row={'rev':13,'tla':20,'tlb':27}
end_row={'rev':14,'tla':21,'tlb':28}
int_row={'rev':16,'tla':23,'tlb':30}
avail_row={'rev':17,'tla':24}
order=['rev','tla','tlb']
beg_cash={3:450}
for c in cols:
    if c>3: beg_cash[c]=req[cols[cols.index(c)-1]]
    ws.cell(row=6,column=c).value=beg_cash[c]
    tc=beg_cash[c]-req[c]+ocf[c]
    ws.cell(row=9,column=c).value=tc
    cash=tc
    prev=cols[cols.index(c)-1] if c>3 else None
    for i,d in enumerate(order):
        b=init[d] if c==3 else end_debt[d][prev]
        ws.cell(row=begb[d],column=c).value=b
        rep=-min(b,cash)
        ws.cell(row=rep_row[d],column=c).value=rep
        e=b+rep
        ws.cell(row=end_row[d],column=c).value=e
        interest=(b+e)/2*rates[d]
        ws.cell(row=int_row[d],column=c).value=interest
        cash=cash+rep-interest
        end_debt[d][c]=e
        if i<2: ws.cell(row=avail_row[d],column=c).value=cash
    ws.cell(row=33,column=c).value=end_debt['rev'][c]+end_debt['tla'][c]+end_debt['tlb'][c]
    ws.cell(row=34,column=c).value=sum(ws.cell(row=int_row[d],column=c).value for d in order)
    ws.cell(row=35,column=c).value=req[c]
wb.save("/mnt/spreadsheet_output/02_05_output.xlsx")
print("saved")

