import openpyxl
from openpyxl.utils import get_column_letter as L
p="/mnt/spreadsheet_data/spreadsheet/06_equity_forecast/06_06_input.xlsx"
wb=openpyxl.load_workbook(p)
ws=wb["Revenue_Forecast"]
ws["E8"]=1740; ws["F12"]=1015; ws["D16"]=680; ws["E27"]=2416; ws["D31"]=1405

def growth_row(r):
    for c in range(4,7):  # D..F quarters
        ws.cell(row=r+1,column=c,value=f"={L(c)}{r}/{L(c-1)}{r}-1")
    ws.cell(row=r+2,column=7,value=f"=SUM(C{r}:F{r})")

areas={"Immunology":8,"Oncology":12,"Neuroscience":16}
for name,r in areas.items(): growth_row(r)

ws["G20"]="=SUM(C20:F20)"
for c in range(4,7):
    ws.cell(row=21,column=c,value=f"={L(c)}20/{L(c-1)}20-1")
for c in range(3,7):
    ws.cell(row=22,column=c,value="=("+ "+".join(f"({L(c)}{r}*{L(c)}{r+2})" for rr in areas.values() for r in [rr])+f")/{L(c)}20")

areasB={"Cardiovascular":27,"Tech Cobolic":31}
for name,r in areasB.items(): growth_row(r)

ws["G35"]="=SUM(C35:F35)"
for c in range(4,7):
    ws.cell(row=36,column=c,value=f"={L(c)}35/{L(c-1)}35-1")
for c in range(3,7):
    ws.cell(row=37,column=c,value="=("+ "+".join(f"({L(c)}{r}*{L(c)}{r+2})" for rr in areasB.values() for r in [rr])+f")/{L(c)}35")

for c in range(3,8):
    ws.cell(row=40,column=c,value=f"={L(c)}20+{L(c)}35")
for c in range(4,7):
    ws.cell(row=41,column=c,value=f"={L(c)}40/{L(c-1)}40-1")
for c in range(3,7):
    ws.cell(row=42,column=c,value=f"=({L(c)}20*{L(c)}22+{L(c)}35*{L(c)}37)/{L(c)}40")

wb.save("/mnt/spreadsheet_output/06_06_output.xlsx")
print("saved")

